}

Method.Source:
/// <summary>
/// find method
/// </summary>
/// <param name = "_mgkGroup">AVAMGKGroup</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>AVAMGKFactors</returns>
public static AVAMGKFactors findGroupId(
    AVAMGKGroup _mgkGroup,
    boolean _selectForUpdate = false)
{
    AVAMGKFactors mgkFactors;

    if(_selectForUpdate)
    {
        mgkFactors.selectForUpdate(_selectForUpdate);
    }

    select firstonly mgkFactors
        where mgkFactors.MGKGroup == _mgkGroup;

    return mgkFactors;
}

/// <summary>
/// find record by rec id
/// </summary>
/// <param name = "_recId">Rec id of the record</param>
/// <param name = "_selectForUpdate">for update</param>
/// <returns>AVAMGKFactors record</returns>
public static AVAMGKFactors findByRecId(RecId _recId, boolean _selectForUpdate = false)
{
    AVAMGKFactors mgkFactors;

    if(_selectForUpdate)
    {
        mgkFactors.selectForUpdate(_selectForUpdate);
    }

    select firstonly mgkFactors
        where mgkFactors.RecId == _recId;

    return mgkFactors;
}

public void update()
{
    AVAMGKFactors lAVAMGKFactors = this.orig();
    super();

    if(lAVAMGKFactors.MGKFactor != this.MGKFactor)
    {
        //NDXHK2MGKHistory::createByAVAMGKFactors(this);
        NDXMGKGroupHistory::createByAVAMGKFactors(this);
    }
}
